"""Round 5, C6 (D5-2): one source-scope rule, the same as the Go engine's.

Every supported in-scope file at or below the size cap is analysed, whatever its
content looks like: minified, vendored, generated, test and fixture code
included. Nothing is excluded for a banner, a header, a file or directory name,
a large literal, line statistics or code appearance (post-commit review item 1:
a file classified from its first 64 KiB was excluded whole). A directory marker
is not evidence either: `pyvenv.cfg`, a dist-info RECORD or an npm
`package.json` can be written by anyone (item 2). The only directory the engine
leaves out is the version-control metadata directory at the scan root, and only
when its layout is real (`HEAD` file, `objects/` and `refs/` directories); a
`.git` anywhere else is ordinary content. An over-cap or unreadable in-scope
file is lost evaluation, never an exclusion, and a probe never blocks or follows
a symlink (item 9).

The tests that pin "an over-cap generated file is declared, not lost" and "a
virtualenv marker prunes" in `test_rem_py4_scope.py` were the round 4 rule; this
file replaces them.
"""

from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
import textwrap
from pathlib import Path

import pytest

from analyzers.ast_analyzer import AnalysisIncomplete, ASTAnalyzer
from analyzers.scope_evidence import NotRegularFile, SourceWalk, read_regular

PYTHON_DIR = Path(__file__).parent.parent

# Fixture source the analyzer scans as text; never executed or imported.
SHELL_ROUTE = (
    "import subprocess\n"
    "from flask import Flask, request\n"
    "app = Flask(__name__)\n"
    "\n"
    "@app.route('/run')\n"
    "def run():\n"
    "    cmd = request.args.get('cmd', '')\n"
    "    subprocess.call(cmd, shell=True)\n"
    "    return 'ok'\n"
)
SHELL = "SEC-PY_SUBPROCESS_SHELL"
EVAL = "SEC-JS_EVAL"


def _write(root: str, files: dict) -> None:
    for rel, content in files.items():
        path = Path(root) / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(content, bytes):
            path.write_bytes(content)
        else:
            path.write_text(content)


def _run(files: dict, setup=None):
    """(findings, AnalysisIncomplete | None, analyzer)."""
    findings: list[dict] = []
    with tempfile.TemporaryDirectory() as d:
        _write(d, files)
        if setup is not None:
            setup(Path(d))
        analyzer = ASTAnalyzer(d, "python")
        try:
            analyzer.run(findings.append)
        except AnalysisIncomplete as exc:
            return findings, exc, analyzer
    return findings, None, analyzer


def _ids(findings: list[dict], rel: str | None = None) -> set:
    return {f["id"] for f in findings if rel is None or f["line"].startswith(rel + ":")}


def _lost(raised) -> dict:
    return dict(raised.files) if raised is not None else {}


# ---------------------------------------------------------------------------
# Item 1: head-only classification excluded a whole file
# ---------------------------------------------------------------------------


def _minified_head(kib: int = 70) -> str:
    """A dense minified-looking line well past the 64 KiB the old classifier
    read, on one line."""
    return "function a(b){return b+1}var c=a(2);" * (kib * 1024 // 36) + "\n"


class TestWholeFileEvidence:
    def test_a_minified_looking_head_does_not_hide_the_rest_of_the_file(self) -> None:
        # The first 70 KiB look minified; the vulnerable handler is after them.
        js = _minified_head() + "function run(req){ eval(req.query.code); }\n"
        findings, raised, analyzer = _run({"static/app.js": js})
        assert raised is None
        assert EVAL in _ids(findings, "static/app.js")
        assert analyzer.excluded == []

    def test_a_minified_bundle_under_the_cap_is_scanned(self) -> None:
        js = "function a(b){return b+1}var c=a(2);" * 80 + "eval(x);\n"
        findings, raised, analyzer = _run({"static/bundle.min.js": js})
        assert raised is None
        assert EVAL in _ids(findings, "static/bundle.min.js")
        assert analyzer.excluded == []

    @pytest.mark.parametrize(
        "header",
        [
            "/*! jQuery v3.7.1 | (c) OpenJS Foundation */\n",
            "// Code generated by protoc-gen-js. DO NOT EDIT.\n",
            "/* @generated */\n",
            "// webpackBootstrap\n",
        ],
    )
    def test_a_forged_banner_or_header_does_not_hide_first_party_code(self, header: str) -> None:
        body = "".join(f"jQuery.fn.m{i} = function () {{ return jQuery(this); }};\n" for i in range(300))
        js = header + body + "app.use((ctx) => { eval(ctx.query.id); });\n" + "//# sourceMappingURL=a.js.map\n"
        findings, raised, analyzer = _run({"static/handler.js": js})
        assert raised is None
        assert EVAL in _ids(findings, "static/handler.js"), header
        assert analyzer.excluded == []

    def test_a_genuine_library_file_under_the_cap_is_scanned_too(self) -> None:
        # A real-looking jQuery is still in scope: the engine cannot prove a
        # banner is honest, so it analyses the file (D5-2).
        body = "".join(f"jQuery.fn.method{i} = function () {{ return jQuery(this); }};\n" for i in range(200))
        js = "/*! jQuery v3.6.0 | (c) OpenJS Foundation */\n" + body + "eval(a)\n"
        findings, raised, analyzer = _run({"static/jquery.js": js})
        assert raised is None and EVAL in _ids(findings, "static/jquery.js")
        assert analyzer.excluded == []

    def test_a_generated_python_file_under_the_cap_is_analysed(self) -> None:
        py = "# Generated by the protocol buffer compiler.  DO NOT EDIT!\n" + SHELL_ROUTE
        findings, raised, analyzer = _run({"msg_pb2.py": py})
        assert raised is None and SHELL in _ids(findings, "msg_pb2.py")
        assert analyzer.excluded == []

    def test_test_and_fixture_code_is_analysed(self) -> None:
        findings, raised, _a = _run({"tests/fixtures/app.py": SHELL_ROUTE, "tests/x.js": "eval(a)\n"})
        assert raised is None
        assert SHELL in _ids(findings, "tests/fixtures/app.py")
        assert EVAL in _ids(findings, "tests/x.js")


class TestOverCapIsLostEvaluation:
    """The cap is the only size rule: whatever a file claims to be, a file the
    engine did not read is a gap, named with its reason."""

    @staticmethod
    def _big_js(first: str) -> str:
        pad = "".join(f"var pad{i} = {i};\n" for i in range(80_000))
        js = first + pad
        assert len(js.encode()) > 1_048_576
        return js

    @pytest.mark.parametrize(
        "first",
        [
            "// Code generated by protoc-gen-js. DO NOT EDIT.\n",
            "/* @generated */\n",
            "/*! jQuery v3.6.0 */\n",
            "",
        ],
    )
    def test_an_oversized_javascript_file_is_lost_whatever_its_header(self, first: str) -> None:
        _f, raised, analyzer = _run({"gen/msg.js": self._big_js(first), "app.py": SHELL_ROUTE})
        assert raised is not None and list(_lost(raised)) == ["gen/msg.js"]
        assert "1 MB" in _lost(raised)["gen/msg.js"]
        assert analyzer.excluded == []

    def test_an_oversized_compiled_file_is_lost(self) -> None:
        js = self._big_js("") + "//# sourceMappingURL=app.js.map\n"
        _f, raised, analyzer = _run({"static/app.js": js})
        assert list(_lost(raised)) == ["static/app.js"]
        assert analyzer.excluded == []

    def test_an_oversized_minified_bundle_is_lost(self) -> None:
        js = "function a(b){return b+1}var c=a(2);" * 40_000
        assert len(js) > 1_048_576
        _f, raised, analyzer = _run({"static/vendor.min.js": js, "app.py": SHELL_ROUTE})
        assert list(_lost(raised)) == ["static/vendor.min.js"]
        assert analyzer.excluded == []

    def test_an_oversized_generated_python_file_is_lost(self) -> None:
        pad = "".join(f"PAD_{i:07d} = {i}\n" for i in range(60_000))
        big = "# Generated by the protocol buffer compiler.  DO NOT EDIT!\n" + pad
        assert len(big.encode()) > 1_048_576
        findings, raised, analyzer = _run({"msg_pb2.py": big, "app.py": SHELL_ROUTE})
        assert list(_lost(raised)) == ["msg_pb2.py"]
        assert analyzer.excluded == []
        assert SHELL in _ids(findings, "app.py")  # the rest is still analysed


# ---------------------------------------------------------------------------
# Item 2: forgeable directory markers
# ---------------------------------------------------------------------------


class TestMarkersAreNotEvidence:
    def test_a_pyvenv_cfg_does_not_prune_the_directory(self) -> None:
        files = {"env/pyvenv.cfg": "home = /usr/bin\n", "env/lib/site.py": SHELL_ROUTE}
        findings, raised, analyzer = _run(files)
        assert raised is None
        assert SHELL in _ids(findings, "env/lib/site.py")
        assert analyzer.excluded == []

    def test_a_dist_info_record_does_not_prune_what_it_names(self) -> None:
        files = {
            "libs/six-1.0.dist-info/RECORD": "six.py,sha256=x,10\npkg/__init__.py,sha256=y,5\n",
            "libs/six.py": SHELL_ROUTE,
            "libs/pkg/__init__.py": SHELL_ROUTE,
        }
        findings, raised, analyzer = _run(files)
        assert raised is None
        assert SHELL in _ids(findings, "libs/six.py") and SHELL in _ids(findings, "libs/pkg/__init__.py")
        assert analyzer.excluded == []

    def test_a_node_modules_package_with_a_package_json_is_scanned(self) -> None:
        files = {
            "node_modules/dep/package.json": json.dumps({"name": "dep", "version": "1.2.3"}),
            "node_modules/dep/index.js": "eval(a)\n",
        }
        findings, raised, analyzer = _run(files)
        assert raised is None and EVAL in _ids(findings, "node_modules/dep/index.js")
        assert analyzer.excluded == []

    def test_site_packages_is_scanned(self) -> None:
        files = {"lib/python3.12/site-packages/x/__init__.py": SHELL_ROUTE}
        findings, raised, analyzer = _run(files)
        assert raised is None and SHELL in _ids(findings)
        assert analyzer.excluded == []

    def test_a_nested_dot_git_with_a_head_file_is_ordinary_content(self) -> None:
        files = {"sub/.git/HEAD": "ref: refs/heads/x\n", "sub/.git/hooks/h.py": SHELL_ROUTE}
        findings, raised, _a = _run(files)
        assert SHELL in _ids(findings, "sub/.git/hooks/h.py")

    def test_a_nested_dot_git_with_a_full_layout_is_still_ordinary_content(self) -> None:
        def make(root: Path) -> None:
            (root / "sub/.git/objects").mkdir(parents=True)
            (root / "sub/.git/refs").mkdir(parents=True)

        files = {"sub/.git/HEAD": "ref: refs/heads/x\n", "sub/.git/hooks/h.py": SHELL_ROUTE}
        findings, _r, _a = _run(files, make)
        assert SHELL in _ids(findings, "sub/.git/hooks/h.py")

    def test_a_root_dot_git_with_only_a_head_file_is_ordinary_content(self) -> None:
        findings, _r, analyzer = _run({".git/HEAD": "ref: x\n", ".git/hooks/h.py": SHELL_ROUTE})
        assert SHELL in _ids(findings, ".git/hooks/h.py")
        assert analyzer.excluded == []

    def test_a_root_dot_git_missing_refs_is_ordinary_content(self) -> None:
        def make(root: Path) -> None:
            (root / ".git/objects").mkdir(parents=True)

        findings, _r, _a = _run({".git/HEAD": "ref: x\n", ".git/hooks/h.py": SHELL_ROUTE}, make)
        assert SHELL in _ids(findings, ".git/hooks/h.py")

    def test_a_real_root_dot_git_is_skipped(self) -> None:
        def make(root: Path) -> None:
            (root / ".git/objects").mkdir(parents=True)
            (root / ".git/refs").mkdir(parents=True)

        findings, raised, _a = _run({".git/HEAD": "ref: refs/heads/main\n", ".git/hooks/h.py": SHELL_ROUTE, "app.py": SHELL_ROUTE}, make)
        assert raised is None
        assert _ids(findings, ".git/hooks/h.py") == set()
        assert SHELL in _ids(findings, "app.py")

    def test_a_symlinked_objects_directory_is_not_a_real_layout(self) -> None:
        def make(root: Path) -> None:
            target = root / "elsewhere"
            target.mkdir()
            (root / ".git").mkdir(exist_ok=True)
            os.symlink(target, root / ".git/objects")
            (root / ".git/refs").mkdir()

        findings, _r, _a = _run({".git/HEAD": "ref: x\n", ".git/hooks/h.py": SHELL_ROUTE}, make)
        assert SHELL in _ids(findings, ".git/hooks/h.py")

    def test_a_symlinked_head_is_not_a_real_layout(self) -> None:
        def make(root: Path) -> None:
            (root / ".git/objects").mkdir(parents=True)
            (root / ".git/refs").mkdir(parents=True)
            (root / "real_head").write_text("ref: x\n")
            os.symlink(root / "real_head", root / ".git/HEAD")

        findings, _r, _a = _run({".git/hooks/h.py": SHELL_ROUTE}, make)
        assert SHELL in _ids(findings, ".git/hooks/h.py")

    def test_a_symlinked_dot_git_is_listed_and_not_followed(self) -> None:
        def make(root: Path) -> None:
            outside = root.parent / (root.name + "-outside")
            (outside / "objects").mkdir(parents=True)
            (outside / "refs").mkdir()
            (outside / "HEAD").write_text("ref: x\n")
            (outside / "h.py").write_text(SHELL_ROUTE)
            os.symlink(outside, root / ".git")
            self._outside = outside

        findings, raised, analyzer = _run({"app.py": "x = 1\n"}, make)
        assert raised is None
        assert (".git/", "symbolic link") in analyzer.excluded
        assert _ids(findings, ".git/h.py") == set()
        import shutil

        shutil.rmtree(self._outside, ignore_errors=True)

    def test_the_walk_lists_nothing_it_did_not_prune(self) -> None:
        with tempfile.TemporaryDirectory() as d:
            _write(d, {"a/b.py": "x = 1\n", "node_modules/p/package.json": '{"name":"p","version":"1"}'})
            walk = SourceWalk(Path(d))
            dirs = [Path(p).relative_to(d).as_posix() for p, _f in walk.walk(record=True)]
            assert dirs == [".", "a", "node_modules", "node_modules/p"]
            assert walk.declared == [] and walk.lost == []


# ---------------------------------------------------------------------------
# The cost of scanning what used to be excluded
# ---------------------------------------------------------------------------


class TestCostOfScanningEverything:
    """A minified, vendored or generated file under the cap is scanned like any
    other (D5-2), so its worst shapes must stay linear."""

    def test_many_sql_template_lines_read_the_file_constants_once(self) -> None:
        import time

        line = "const q = `SELECT * FROM t WHERE id = ${id}`;\n"
        js = "const TABLE = 'users';\n" + line * (1_000_000 // len(line))
        assert 900_000 < len(js.encode()) < 1_048_576
        start = time.monotonic()
        findings, raised, _a = _run({"static/queries.js": js})
        assert raised is None
        assert time.monotonic() - start < 20
        assert "SEC-JS_SQL_TEMPLATE" in _ids(findings)

    def test_a_megabyte_minified_line_is_linear(self) -> None:
        import time

        js = "var a=`SELECT ${x}`;eval(b);" * 35_000
        assert 900_000 < len(js.encode()) < 1_048_576
        start = time.monotonic()
        findings, raised, _a = _run({"static/bundle.min.js": js})
        assert raised is None
        assert time.monotonic() - start < 20
        assert EVAL in _ids(findings)


# ---------------------------------------------------------------------------
# Item 9: probing never blocks
# ---------------------------------------------------------------------------

_DRIVER = textwrap.dedent(
    """
    import json, sys
    sys.path.insert(0, {python_dir!r})
    from analyzers.ast_analyzer import AnalysisIncomplete, ASTAnalyzer
    findings = []
    lost = []
    a = ASTAnalyzer(sys.argv[1], "python")
    try:
        a.run(findings.append)
    except AnalysisIncomplete as exc:
        lost = exc.files
    print(json.dumps({{"ids": [f["id"] for f in findings], "lost": lost, "excluded": a.excluded}}))
    """
)


@pytest.mark.skipif(not hasattr(os, "mkfifo"), reason="needs named pipes")
class TestNeverBlocks:
    def _scan(self, root: Path) -> dict:
        proc = subprocess.run(
            [sys.executable, "-c", _DRIVER.format(python_dir=str(PYTHON_DIR)), str(root)],
            capture_output=True,
            text=True,
            timeout=30,  # a blocking open of a FIFO would never return
        )
        assert proc.returncode == 0, proc.stderr
        return json.loads(proc.stdout.splitlines()[-1])

    def test_a_named_pipe_with_a_source_name_is_lost_evaluation_not_a_hang(self, tmp_path: Path) -> None:
        os.mkfifo(tmp_path / "pipe.py")
        os.mkfifo(tmp_path / "pipe.js")
        (tmp_path / "app.py").write_text(SHELL_ROUTE)
        out = self._scan(tmp_path)
        assert SHELL in out["ids"]
        assert sorted(rel for rel, _why in out["lost"]) == ["pipe.js", "pipe.py"]
        assert all("not a regular file" in why for _rel, why in out["lost"])

    def test_a_named_pipe_as_a_git_marker_does_not_block(self, tmp_path: Path) -> None:
        (tmp_path / ".git/objects").mkdir(parents=True)
        (tmp_path / ".git/refs").mkdir()
        os.mkfifo(tmp_path / ".git/HEAD")
        (tmp_path / ".git/h.py").write_text(SHELL_ROUTE)
        out = self._scan(tmp_path)
        assert SHELL in out["ids"]  # not a regular HEAD: ordinary content


@pytest.mark.skipif(not hasattr(os, "mkfifo"), reason="needs named pipes")
class TestReadRegular:
    """The read itself is as careful as the probe: a path swapped for a pipe or a
    link after the walk listed it cannot stall the scan or leave the root."""

    def test_a_regular_file_is_read(self, tmp_path: Path) -> None:
        (tmp_path / "a.py").write_bytes(b"x = 1\n")
        assert read_regular(tmp_path / "a.py") == b"x = 1\n"

    def test_a_named_pipe_is_refused_without_blocking(self, tmp_path: Path) -> None:
        os.mkfifo(tmp_path / "p.py")
        with pytest.raises(NotRegularFile):
            read_regular(tmp_path / "p.py")

    def test_a_symlink_is_refused_not_followed(self, tmp_path: Path) -> None:
        (tmp_path / "real.py").write_text("x = 1\n")
        os.symlink(tmp_path / "real.py", tmp_path / "link.py")
        with pytest.raises(OSError):
            read_regular(tmp_path / "link.py")

    def test_a_missing_file_is_an_oserror(self, tmp_path: Path) -> None:
        with pytest.raises(OSError):
            read_regular(tmp_path / "missing.py")
